-- Seed: Class panel actions (combat class panels)
-- Catálogo SSOT (C009 economia · C010 painel). Recursos de subclasse: S002/S003 + C014 (mago).

DELETE FROM rpg.phb_class_panel_action WHERE panel_key = 'wizard|spell-mastery';
DELETE FROM rpg.phb_class_panel_action WHERE panel_key = 'warlock|fiend|dark-ones-own-luck';
-- Pools base do Patrulheiro (Marca / Incansável / Véu) só na Economia (C009), não no painel.
DELETE FROM rpg.phb_class_panel_action WHERE panel_key IN (
  'ranger|hunters-mark-free',
  'ranger|tireless',
  'ranger|natures-veil'
);

-- Lâminas Psíquicas: ataques virtuais na ficha (Furtivo/Astuto no card), não no painel.
DELETE FROM rpg.phb_class_panel_action WHERE panel_key IN (
  'rogue|soulknife|psychic-blade-main',
  'rogue|soulknife|psychic-blade-bonus'
);

-- Legado Bardo (nome 2014).
DELETE FROM rpg.phb_class_panel_action WHERE panel_key = 'bard|glamour|enthralling-performance';

-- Forma Selvagem (besta): pool ± só na Economia; seletor de ficha = futuro.
DELETE FROM rpg.phb_class_panel_action WHERE panel_key = 'druid|wild-shape';

